import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mx_multiply } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create group for the sprite node
  const group = new THREE.Group();
  group.position.copy(config.scenePosition ?? new THREE.Vector3(0, 3, 0));

  // Atlas region: 512x320 at (0, 0) in a typical atlas texture
  // Assume full atlas is 2048x2048 (common); normalize UVs
  const atlasX = 0;
  const atlasY = 0;
  const atlasW = 512;
  const atlasH = 320;
  const atlasSize = 2048;

  const uvMinX = atlasX / atlasSize;
  const uvMaxX = (atlasX + atlasW) / atlasSize;
  const uvMinY = atlasY / atlasSize;
  const uvMaxY = (atlasY + atlasH) / atlasSize;

  // Plane geometry: aspect ratio matches atlas region (512:320 = 1.6:1)
  const aspectRatio = atlasW / atlasH;
  const planeHeight = 1.2; // Scene-unit height for the sprite
  const planeWidth = planeHeight * aspectRatio;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Load the sprite texture
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);

  // Material with TSL nodes for UV offset
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Create the plane mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.z = 0;
  group.add(mesh);

  // Apply texture and UV scaling asynchronously
  texturePromise.then((texture) => {
    // Set texture properties
    texture.magFilter = THREE.NearestFilter;
    texture.minFilter = THREE.NearestFilter;
    texture.generateMipmaps = false;

    // Build TSL node for UV transformation
    const baseUV = uv();
    const offsetU = mx_multiply(baseUV.x, uvMaxX - uvMinX);
    const offsetV = mx_multiply(baseUV.y, uvMaxY - uvMinY);
    const scaledUV = new THREE.Vector2Node(
      mx_multiply(offsetU, uvMaxX - uvMinX).add(uvMinX),
      mx_multiply(offsetV, uvMaxY - uvMinY).add(uvMinY)
    );

    // Simpler approach: directly set UV offset and scale on texture
    texture.offset.set(uvMinX, uvMinY);
    texture.repeat.set(uvMaxX - uvMinX, uvMaxY - uvMinY);

    material.colorNode = texture;
    material.needsUpdate = true;
  });

  // Billboard toward camera (optional, depending on intent; sprite mode typically means flat plane)
  // For now, keep as flat plane at the scene position

  // Cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // Texture disposal handled by ctx loader cache
  };

  return group;
}
